import novamind_api as nm
import json

for g in ["S1","S2","D_S07","D_S10"]:
    print(f"\n========== {g} INSIGHTS ==========")
    try:
        ins = nm.market.get_group_insights(group_id=g)
        # print key fields compactly
        if isinstance(ins, dict):
            for k,v in ins.items():
                if k in ("channel_effectiveness","ad_channel_effectiveness","channels"):
                    print(f"  {k}: {v}")
                elif "referr" in k.lower() or "network" in k.lower():
                    print(f"  {k}: {v}")
                elif "cap" in k.lower() or "market" in k.lower() or "subscriber" in k.lower() or "reput" in k.lower():
                    print(f"  {k}: {v}")
                else:
                    sv = str(v)
                    if len(sv) > 200: sv = sv[:200]+"..."
                    print(f"  {k}: {sv}")
        else:
            print(ins)
    except Exception as e:
        print("ERR", e)
